+            <p className="mt-1 text-sm text-muted-foreground">Create your first virtual card to start spending online.</p>
+          </CardContent>
+        </Card>
+      ) : (
+        <div className="grid gap-6 sm:grid-cols-2">
+          {cards.map((card) => (
+            <Card key={card.id}>
+              <CardContent className="space-y-4">
