+                    <span className="flex items-center gap-1.5 text-xs text-muted-foreground">
+                      <Globe className="size-3.5" /> Online
+                      <Switch checked={card.onlineEnabled} onCheckedChange={() => toast.info("Card controls update in Phase 2")} />
+                    </span>
+                    <Button
