+/* ============================================================
+   Capitech Bank — Design System (Tailwind CSS v4)
+   Brand: professional fintech — deep blue + navy + teal accent
+   ============================================================ */
+
+@import "tailwindcss";
+/* tw-animate-css vendored locally (package exports map is incompatible with Turbopack CSS resolution) */
+@import "./tw-animate.css";
+
+@theme inline {
+  /* Brand blue (primary) */
+  --color-brand-50: #eff5ff;
+  --color-brand-100: #dbe8fe;
+  --color-brand-200: #bfd7fe;
+  --color-brand-300: #93bbfd;
+  --color-brand-400: #6096fa;
+  --color-brand-500: #3b76f6;
+  --color-brand-600: #2557eb;
+  --color-brand-700: #1d43d8;
+  --color-brand-800: #1e38ae;
+  --color-brand-900: #1e3389;
+  --color-brand-950: #172153;
+
+  /* Navy (dark surfaces / hero) */
+  --color-navy-50: #f6f7f9;
+  --color-navy-100: #eceef2;
+  --color-navy-200: #d5dae3;
+  --color-navy-300: #b1bccd;
+  --color-navy-400: #8797af;
+  --color-navy-500: #687a96;
+  --color-navy-600: #52627c;
