+  --color-accent-foreground: var(--accent-foreground);
+  --color-destructive: var(--destructive);
+  --color-destructive-foreground: var(--destructive-foreground);
+  --color-border: var(--border);
+  --color-input: var(--input);
+  --color-ring: var(--ring);
+  --color-chart-1: var(--chart-1);
+  --color-chart-2: var(--chart-2);
+  --color-chart-3: var(--chart-3);
+  --color-chart-4: var(--chart-4);
+  --color-chart-5: var(--chart-5);
+
+  --radius-sm: calc(var(--radius) - 4px);
+  --radius-md: calc(var(--radius) - 2px);
+  --radius-lg: var(--radius);
+  --radius-xl: calc(var(--radius) + 4px);
+}
+
+:root {
+  --background: oklch(0.985 0.002 247);
+  --foreground: oklch(0.15 0.03 262);
+  --card: oklch(1 0 0);
+  --card-foreground: oklch(0.15 0.03 262);
+  --popover: oklch(1 0 0);
+  --popover-foreground: oklch(0.15 0.03 262);
+  --primary: #2557eb;
+  --primary-foreground: oklch(0.985 0.002 247);
+  --secondary: #f1f5f9;
+  --secondary-foreground: #1e3389;
+  --muted: #f1f5f9;
+  --muted-foreground: #64748b;
+  --accent: #0d9488;
+  --accent-foreground: #ffffff;
+  --destructive: #ef4444;
+  --destructive-foreground: #ffffff;
+  --border: oklch(0.922 0.007 247);
+  --input: oklch(0.922 0.007 247);
+  --ring: #2557eb;
+  --radius: 0.625rem;
+  --chart-1: #2557eb;
+  --chart-2: #14b8a6;
+  --chart-3: #f59e0b;
+  --chart-4: #8b5cf6;
+  --chart-5: #f43f5e;
+}
+
+.dark {
+  --background: #0b1220;
+  --foreground: oklch(0.97 0.005 247);
+  --card: #0f1a2e;
+  --card-foreground: oklch(0.97 0.005 247);
+  --popover: #0f1a2e;
+  --popover-foreground: oklch(0.97 0.005 247);
+  --primary: #6096fa;
+  --primary-foreground: #0b1220;
+  --secondary: #1e293b;
+  --secondary-foreground: #dbe8fe;
+  --muted: #1e293b;
+  --muted-foreground: #94a3b8;
+  --accent: #2dd4bf;
+  --accent-foreground: #0b1220;
+  --destructive: #f87171;
+  --destructive-foreground: #0b1220;
+  --border: #1e293b;
+  --input: #1e293b;
+  --ring: #6096fa;
+}
+
+@layer base {
+  * {
+    border-color: var(--border);
+  }
+  html {
+    scroll-behavior: smooth;
+  }
+  body {
+    background-color: var(--background);
+    color: var(--foreground);
+    font-family: var(--font-sans);
+    -webkit-font-smoothing: antialiased;
+    -moz-osx-font-smoothing: grayscale;
+  }
+  ::selection {
+    background-color: var(--ring);
+    color: var(--primary-foreground);
+  }
+}

