  --color-brand-800: #1e38ae;
  --color-brand-900: #1e3389;
  --color-brand-950: #172153;

  /* Navy (dark surfaces / hero) */
  --color-navy-50: #f6f7f9;
  --color-navy-100: #eceef2;
  --color-navy-200: #d5dae3;
  --color-navy-300: #b1bccd;
  --color-navy-400: #8797af;
