"use client";

import { useState } from "react";
import { PiggyBank, Plus } from "lucide-react";
import { Badge, Button, Card, CardContent, CardDescription, CardHeader, CardTitle, Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger, Input, Label, Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@capitech/ui";
import { formatMoney, formatPercent, formatDate } from "@capitech/lib";
import { toast } from "sonner";
import { cn } from "@capitech/ui";
import { getBrowserClient, isSupabaseConfigured } from "@/lib/supabase";
import type { DepositVM } from "@/lib/data";

const TERMS = [7, 30, 90, 180, 365];

function OpenDepositDialog({ accountId }: { accountId: string }) {
  const [open, setOpen] = useState(false);
  const [principal, setPrincipal] = useState("");
  const [term, setTerm] = useState(90);
  const [rollover, setRollover] = useState(false);
  const [loading, setLoading] = useState(false);

  async function handleOpen() {
    setLoading(true);
    if (isSupabaseConfigured()) {
      const supabase = getBrowserClient();
      const { data: { user } } = await supabase.auth.getUser();
      const { data: customer } = await supabase.from("customers").select("id").maybeSingle();
      const start = new Date();
      const maturity = new Date(start);
      maturity.setDate(maturity.getDate() + term);
      const { error } = await supabase.from("deposits").insert({
        account_id: accountId,
        customer_id: customer?.id,
        product_id: "prod-deposit",
        principal,
        currency: "USD",
        interest_rate: "4.25",
        term_days: term,
        start_date: start.toISOString().slice(0, 10),
        maturity_date: maturity.toISOString().slice(0, 10),
        interest_accrued: "0",
        rollover,
        status: "active",
      });
      if (error) {
        toast.error(error.message);
        setLoading(false);
        return;
      }
      toast.success("Term deposit opened");
      setOpen(false);
      window.location.reload();
      return;
    }
    await new Promise((r) => setTimeout(r, 700));
    toast.success(`Term deposit of ${formatMoney(principal || "0", "USD")} opened`);
    setOpen(false);
    window.location.reload();
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>
          <Plus className="size-4" /> Open deposit
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Open a term deposit</DialogTitle>
          <DialogDescription>Lock in a fixed rate for a fixed term. Interest accrues daily.</DialogDescription>
        </DialogHeader>
        <div className="space-y-4 py-2">
          <div className="space-y-2">
            <Label htmlFor="principal">Principal (USD)</Label>
            <Input id="principal" inputMode="decimal" value={principal} onChange={(e) => setPrincipal(e.target.value)} placeholder="1000.00" />
          </div>
          <div className="space-y-2">
            <Label>Term</Label>
            <Select value={term.toString()} onValueChange={(v) => setTerm(Number(v))}>
              <SelectTrigger className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {TERMS.map((t) => (
                  <SelectItem key={t} value={t.toString()}>{t} days · {formatPercent(t === 7 ? 2.5 : t === 30 ? 3.1 : t === 90 ? 4.25 : t === 180 ? 4.75 : 5.2)}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <label className="flex items-center gap-3 text-sm text-navy-950">
            <input
              type="checkbox"
              checked={rollover}
              onChange={(e) => setRollover(e.target.checked)}
              className="size-4 rounded border-border accent-brand-600"
            />
            Automatically renew at maturity
          </label>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button>
          <Button onClick={handleOpen} disabled={loading || !principal}>{loading ? "Opening…" : "Open deposit"}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

export function DepositsManager({ deposits, accountId }: { deposits: DepositVM[]; accountId: string }) {
  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-navy-950">Term deposits</h1>
          <p className="mt-1 text-sm text-muted-foreground">Grow your savings with fixed-rate deposits.</p>
        </div>
        <OpenDepositDialog accountId={accountId} />
      </div>

      {deposits.length === 0 ? (
        <Card>
          <CardContent className="py-14 text-center">
            <PiggyBank className="mx-auto size-10 text-muted-foreground" />
            <h3 className="mt-4 font-semibold text-navy-950">No deposits yet</h3>
            <p className="mt-1 text-sm text-muted-foreground">Lock in competitive rates starting from 7 days.</p>
          </CardContent>
        </Card>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2">
          {deposits.map((dep) => (
            <Card key={dep.id} className={cn(dep.status === "matured" && "opacity-70")}>
              <CardHeader>
                <CardTitle className="flex items-center justify-between">
                  {formatMoney(dep.principal, dep.currency)}
                  <Badge variant={dep.status === "active" ? "success" : dep.status === "matured" ? "info" : "neutral"}>
                    {dep.status}
                  </Badge>
                </CardTitle>
                <CardDescription>
                  {formatPercent(dep.interestRate)} p.a. · {dep.termDays} days
                </CardDescription>
              </CardHeader>
              <CardContent className="grid grid-cols-2 gap-3 text-sm">
                <div className="rounded-lg bg-muted px-3 py-2">
                  <p className="text-xs text-muted-foreground">Matures</p>
                  <p className="font-semibold text-navy-950">{formatDate(dep.maturityDate)}</p>
                </div>
                <div className="rounded-lg bg-muted px-3 py-2">
                  <p className="text-xs text-muted-foreground">Accrued interest</p>
                  <p className="font-semibold text-emerald-600">{formatMoney(dep.interestAccrued, dep.currency)}</p>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

import { getAccounts, getDeposits } from "@/lib/data";
import { DepositsManager } from "@/components/deposits-manager";

export default async function DepositsPage() {
  const [deposits, accounts] = await Promise.all([getDeposits(), getAccounts()]);
  return <DepositsManager deposits={deposits} accountId={accounts[0]?.id ?? ""} />;
}

import Link from "next/link";
import { CheckCircle2, Bell, ShieldCheck, CreditCard, Info } from "lucide-react";
import { Badge, Button } from "@capitech/ui";
import { formatRelativeTime } from "@capitech/lib";
import { getNotifications } from "@/lib/data";
import { MarkNotificationsRead } from "@/components/mark-notifications-read";
import { cn } from "@capitech/ui";

function iconFor(type: string) {
  switch (type) {
    case "transaction":
      return { icon: CheckCircle2, cls: "bg-emerald-100 text-emerald-600" };
    case "security":
      return { icon: ShieldCheck, cls: "bg-brand-50 text-brand-600" };
    case "card":
      return { icon: CreditCard, cls: "bg-navy-100 text-navy-600" };
    default:
      return { icon: Info, cls: "bg-muted text-muted-foreground" };
  }
}

export default async function NotificationsPage() {
  const notifications = await getNotifications();

  return (
    <div className="mx-auto max-w-3xl space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="flex items-center gap-2 text-2xl font-bold tracking-tight text-navy-950">
            <Bell className="size-6 text-brand-600" /> Notifications
          </h1>
          <p className="mt-1 text-sm text-muted-foreground">Transaction alerts, security and account updates.</p>
        </div>
        <MarkNotificationsRead />
      </div>

      {notifications.length === 0 ? (
        <div className="rounded-2xl border border-dashed border-border py-16 text-center">
          <p className="text-sm text-muted-foreground">No notifications yet.</p>
        </div>
      ) : (
        <ul className="space-y-3">
          {notifications.map((n) => {
            const { icon: Icon, cls } = iconFor(n.type);
            return (
              <li
                key={n.id}
                className={cn(
                  "flex gap-4 rounded-2xl border border-border bg-card p-4 shadow-sm",
                  !n.read && "border-brand-200 bg-brand-50/30"
                )}
              >
                <div className={cn("flex size-10 shrink-0 items-center justify-center rounded-full", cls)}>
                  <Icon className="size-5" />
                </div>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center justify-between gap-2">
                    <p className="font-medium text-navy-950">{n.title}</p>
                    {!n.read && <Badge variant="info">New</Badge>}
                  </div>
                  <p className="mt-1 text-sm text-muted-foreground">{n.body}</p>
                  <p className="mt-1.5 text-xs text-muted-foreground/70">{formatRelativeTime(n.createdAt)}</p>
                </div>
              </li>
            );
          })}
        </ul>
      )}

      <div className="rounded-2xl border border-border bg-card p-5 text-sm text-muted-foreground">
        Manage email preferences in{" "}
        <Link href="/profile" className="font-medium text-brand-600 hover:underline">Profile &amp; Security</Link>.
      </div>
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { CheckCheck } from "lucide-react";
import { Button } from "@capitech/ui";
import { toast } from "sonner";
import { getBrowserClient, isSupabaseConfigured } from "@/lib/supabase";

export function MarkNotificationsRead() {
  const router = useRouter();

  async function markAll() {
    if (!isSupabaseConfigured()) {
      toast.success("All notifications marked as read");
      return;
    }
    const supabase = getBrowserClient();
    const { error } = await supabase.from("notifications").update({ read: true }).eq("read", false);
    if (error) toast.error(error.message);
    else toast.success("All notifications marked as read");
    router.refresh();
  }

  return (
    <Button variant="outline" size="sm" onClick={markAll}>
      <CheckCheck className="size-4" /> Mark all read
    </Button>
  );
}

