import { createBrowserClient } from "@capitech/db";

/** Browser client for client components. */
export function getBrowserClient() {
  return createBrowserClient();
}

export function isSupabaseConfigured(): boolean {
  return !!process.env.NEXT_PUBLIC_SUPABASE_URL && !!process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
}

import { createServerClient } from "@capitech/db";
import { cookies } from "next/headers";

/** Server client bound to the request cookies — server components only. */
export async function getServerClient() {
  const cookieStore = await cookies();
  return createServerClient({
    getAll: () => cookieStore.getAll(),
    setAll: (cookiesToSet) => {
      try {
        cookiesToSet.forEach(({ name, value, options }) => cookieStore.set(name, value, options));
      } catch {
        // Called from a Server Component — safe to ignore when middleware refreshes sessions
      }
    },
  });
}

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  transpilePackages: ["@capitech/ui", "@capitech/db", "@capitech/lib"],
};

export default nextConfig;

import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  transpilePackages: ["@capitech/ui", "@capitech/db", "@capitech/lib"],
};

export default nextConfig;

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { createServerClient } from "@supabase/ssr";

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
const COOKIE_DOMAIN = process.env.NEXT_PUBLIC_COOKIE_DOMAIN ?? "";
const LANDING_URL = process.env.NEXT_PUBLIC_LANDING_URL ?? "http://localhost:3000";

export async function proxy(request: NextRequest) {
  let response = NextResponse.next({ request });

  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
    return response;
  }

  const supabase = createServerClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    cookies: {
      getAll() {
        return request.cookies.getAll();
      },
      setAll(cookiesToSet) {
        cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value));
        response = NextResponse.next({ request });
        cookiesToSet.forEach(({ name, value, options }) => {
          response.cookies.set(name, value, {
            ...options,
            ...(COOKIE_DOMAIN ? { domain: COOKIE_DOMAIN } : {}),
          });
        });
      },
    },
  });

  const {
    data: { user },
  } = await supabase.auth.getUser();

  if (!user) {
    const url = request.nextUrl.clone();
    url.pathname = "/sign-in";
    return NextResponse.redirect(new URL(url.pathname, LANDING_URL));
  }

  // Only staff roles may use the back office
  const { data: profile } = await supabase.from("profiles").select("role").maybeSingle();
  const role = profile?.role;
  const isStaff = role && (role.startsWith("staff_") || role === "super_admin");
  if (!isStaff) {
    const url = request.nextUrl.clone();
    url.pathname = "/";
    return NextResponse.redirect(new URL(url.pathname, LANDING_URL));
  }

  return response;
}

export const config = {
  matcher: ["/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)"],
};

import type { Metadata, Viewport } from "next";
