-      case when substring(p_iban from pos for 1) ~ '[A-Z]'
-           then (ascii(substring(p_iban from pos for 1)) - 55)::text
-           else substring(p_iban from pos for 1)
-      end
-    )
-    from digits
-    where pos <= length(p_iban)
-  ),
-  numbered as (select acc from digits order by pos desc limit 1)
-  select mod(cast(acc as numeric), 97) from numbered
+declare
+  v_rearranged text := substr(p_iban, 5) || substr(p_iban, 1, 4);
