/* --- corporate demo (if owner exists) --- */
if (corpOwner) {
  const { data: corpCustomer } = await supabase
    .from("customers")
    .upsert(
      {
        tenant_id: tenantId,
        profile_id: corpOwner.id,
        customer_no: "CAP-000200",
        customer_type: "corporate",
        kyc_level: "level_2",
        kyc_status: "approved",
        legal_name: "Acme Trading LLC",
        registration_number: "AE-88412",
        country_of_incorporation: "AE",
        industry: "Technology",
        risk_score: 28,
      },
      { onConflict: "customer_no" }
    )
    .select()
    .single();

  const { data: existingOrg } = await supabase
    .from("organizations")
    .select("id")
    .eq("legal_name", "Acme Trading LLC")
    .maybeSingle();

  let org = existingOrg;
  if (!org) {
    const { data: created, error: oErr } = await supabase
      .from("organizations")
      .insert({
        tenant_id: tenantId,
        customer_id: corpCustomer.id,
        legal_name: "Acme Trading LLC",
        registration_number: "AE-88412",
        country_of_incorporation: "AE",
        kyc_status: "approved",
        risk_score: 28,
      })
      .select()
      .single();
    if (oErr) throw oErr;
    org = created;
  }

  const { data: existingMember } = await supabase
    .from("organization_members")
    .select("id")
    .eq("organization_id", org.id)
    .eq("profile_id", corpOwner.id)
    .maybeSingle();
  if (!existingMember) {
    await supabase.from("organization_members").insert({
      tenant_id: tenantId,
      organization_id: org.id,
      profile_id: corpOwner.id,
      role_title: "Managing Director",
      is_signatory: true,
      approval_threshold: 250000,
      status: "active",
    });
  }

  const product = byCode["CORP_USD"];
  const { data: existingCorpAcct } = await supabase
    .from("accounts")
    .select("id")
    .eq("account_no", "9900112233")
    .maybeSingle();
  if (!existingCorpAcct) {
    await supabase.from("accounts").insert({
      tenant_id: tenantId,
      account_no: "9900112233",
      iban: makeIban("AE", "9900112233"),
      swift_bic: "CAPTAEXX",
      product_id: product.id,
      coa_account_id: product.coa_account_id,
      owner_type: "organization",
      owner_id: org.id,
      currency: "USD",
      status: "active",
      nickname: "Operating",
      ledger_balance: 152340.9,
      available_balance: 152340.9,
    });
    console.log("corporate account: 9900112233 USD");
  }
}

