===================================================================
--- apps/customer/components/transfer-form.tsx	
+++ apps/customer/components/transfer-form.tsx	
@@ -1,172 +1,172 @@
 "use client";

 import { useState } from "react";
 import { ArrowLeftRight, CheckCircle2, ShieldCheck } from "lucide-react";
 import { Alert, AlertDescription, Button, Card, CardContent, CardDescription, CardHeader, CardTitle, Input, Label, Select, SelectContent, SelectItem, SelectTrigger, SelectValue, Textarea } from "@capitech/ui";
 import { formatMoney, parseAmount, isValidAmount } from "@capitech/lib";
 import { toast } from "@capitech/ui";
 import { getBrowserClient, isSupabaseConfigured } from "@/lib/supabase-browser";
 import type { AccountVM } from "@/lib/data";

 export function TransferForm({ accounts }: { accounts: AccountVM[] }) {
   const [fromAccount, setFromAccount] = useState(accounts[0]?.id ?? "");
   const [toAccount, setToAccount] = useState("");
   const [amount, setAmount] = useState("");
   const [narration, setNarration] = useState("");
   const [reference, setReference] = useState("");
   const [loading, setLoading] = useState(false);
   const [success, setSuccess] = useState(false);

   const selectedAccount = accounts.find((a) => a.id === fromAccount);
   const amountValid = selectedAccount ? isValidAmount(amount, selectedAccount.currency) : false;
   const amountNumber = selectedAccount && amountValid ? Number(amount) : 0;
   const insufficient = selectedAccount ? amountNumber > Number(selectedAccount.availableBalance) : false;

   async function handleSubmit(e: React.FormEvent) {
     e.preventDefault();
     if (!selectedAccount) return;
     setLoading(true);

     if (isSupabaseConfigured()) {
       const supabase = getBrowserClient();
       const { data: { user } } = await supabase.auth.getUser();
       const { error } = await supabase.from("payment_orders").insert({
         tx_type: toAccount.length >= 6 && toAccount.length <= 34 && /^\d+$/.test(toAccount.replace(/\s/g, ""))
           ? "internal_transfer"
           : "withdrawal",
         status: "pending",
         amount: parseAmount(amount),
         currency: selectedAccount.currency,
         from_account_id: fromAccount,
-        to_account_no: toAccount,
+        to_iban: toAccount.replace(/\s/g, ""),
         narration: narration || null,
         reference: reference || null,
         created_by: user?.id,
       });
       if (error) {
         toast.error(error.message);
         setLoading(false);
         return;
       }
       toast.success("Transfer scheduled for processing");
       setSuccess(true);
       setLoading(false);
       return;
     }

     // Demo mode: simulate success
     await new Promise((r) => setTimeout(r, 800));
     toast.success(`Transfer of ${formatMoney(amount, selectedAccount.currency)} initiated`);
     setSuccess(true);
     setLoading(false);
   }

   if (success) {
     return (
       <Card className="max-w-xl">
         <CardContent className="py-12 text-center">
           <div className="mx-auto flex size-14 items-center justify-center rounded-full bg-emerald-100 text-emerald-600">
             <CheckCircle2 className="size-7" />
           </div>
           <h2 className="mt-5 text-xl font-bold text-navy-950">Transfer initiated</h2>
           <p className="mx-auto mt-2 max-w-sm text-sm text-muted-foreground">
             {formatMoney(amount, selectedAccount?.currency ?? "USD")} on its way to{" "}
             <span className="font-medium text-navy-950">{toAccount}</span>. You will receive a
             notification when it settles.
           </p>
           <Button className="mt-6" onClick={() => { setSuccess(false); setAmount(""); setToAccount(""); }}>
             Make another transfer
           </Button>
         </CardContent>
       </Card>
     );
   }

   return (
     <Card className="max-w-xl">
       <CardHeader>
         <CardTitle className="flex items-center gap-2">
           <ArrowLeftRight className="size-5 text-brand-600" /> New transfer
         </CardTitle>
         <CardDescription>Send money instantly to another Capitech account or to an external IBAN.</CardDescription>
       </CardHeader>
       <CardContent>
         <form onSubmit={handleSubmit} className="space-y-5">
           <div className="space-y-2">
             <Label htmlFor="from">From account</Label>
             <Select value={fromAccount} onValueChange={setFromAccount}>
               <SelectTrigger id="from" className="w-full">
                 <SelectValue placeholder="Select account" />
               </SelectTrigger>
               <SelectContent>
                 {accounts.map((account) => (
                   <SelectItem key={account.id} value={account.id}>
                     {account.nickname ?? account.productName} · {account.currency} · {formatMoney(account.availableBalance, account.currency)}
                   </SelectItem>
                 ))}
               </SelectContent>
             </Select>
           </div>

           <div className="space-y-2">
             <Label htmlFor="to">Recipient</Label>
             <div className="relative">
               <ShieldCheck className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-brand-600" />
               <Input
                 id="to"
                 required
                 value={toAccount}
                 onChange={(e) => setToAccount(e.target.value)}
                 placeholder="Capitech account number or IBAN"
                 className="pl-9"
               />
             </div>
             <p className="text-xs text-muted-foreground">For external transfers, enter the full IBAN (e.g. DE89 3704 0044 0532 0130 00).</p>
           </div>

           <div className="space-y-2">
             <Label htmlFor="amount">Amount</Label>
             <div className="relative">
               <Input
                 id="amount"
                 required
                 inputMode="decimal"
                 value={amount}
                 onChange={(e) => setAmount(e.target.value)}
                 placeholder="0.00"
                 className="h-12 text-xl font-semibold"
               />
               <span className="absolute right-3 top-1/2 -translate-y-1/2 text-sm font-medium text-muted-foreground">
                 {selectedAccount?.currency ?? "USD"}
               </span>
             </div>
             {selectedAccount && (
               <p className="text-xs text-muted-foreground">
                 Available: {formatMoney(selectedAccount.availableBalance, selectedAccount.currency)}
               </p>
             )}
             {insufficient && (
               <Alert variant="destructive" className="py-2">
                 <AlertDescription>Insufficient funds for this transfer.</AlertDescription>
               </Alert>
             )}
           </div>

           <div className="space-y-2">
             <Label htmlFor="narration">Narration (optional)</Label>
             <Textarea id="narration" rows={2} value={narration} onChange={(e) => setNarration(e.target.value)} placeholder="What is this payment for?" />
           </div>

           <div className="space-y-2">
             <Label htmlFor="reference">Reference (optional)</Label>
             <Input id="reference" value={reference} onChange={(e) => setReference(e.target.value)} placeholder="Invoice #123" maxLength={40} />
           </div>

           <Button type="submit" size="lg" className="w-full" disabled={loading || !amountValid || insufficient}>
             {loading ? "Sending…" : `Transfer ${amount ? formatMoney(amount, selectedAccount?.currency ?? "USD") : ""}`.trim()}
           </Button>
         </form>
       </CardContent>
     </Card>
   );
 }

Index: supabase/apply-hotfix2.sql
===================================================================
--- supabase/apply-hotfix2.sql	
+++ supabase/apply-hotfix2.sql	
@@ -0,0 +1,139 @@
+-- ============================================================
+-- Capitech Bank — HOTFIX 2 (v_fee_lines type fix)
+-- Paste into: Supabase Dashboard → SQL Editor → Run
+-- Fixes: execute_payment failed with 'Token ... is invalid' (jsonb)
+-- ============================================================
+
+create or replace function public.execute_payment(
+  p_order_id uuid,
+  p_actor uuid default auth.uid(),
+  p_approve boolean default true
+)
+returns public.payment_orders
+language plpgsql
+security definer
+set search_path = public
+as $$
+declare
+  v_tenant uuid := public.current_tenant_id();
+  v_order public.payment_orders%rowtype;
+  v_from public.accounts%rowtype;
+  v_to public.accounts%rowtype;
+  v_nostro uuid;
+  v_lines jsonb;
+  v_fee_lines uuid;
+  v_fee_amount numeric(20,2);
+  v_dest_account uuid;
+begin
+  if v_tenant is null then
+    raise exception 'Not authenticated';
+  end if;
+
+  select * into v_order from public.payment_orders
+  where id = p_order_id and tenant_id = v_tenant;
+  if v_order is null then
+    raise exception 'Order not found';
+  end if;
+  if v_order.status <> 'pending' then
+    raise exception 'Order is not pending (status: %)', v_order.status;
+  end if;
+
+  -- maker–checker: creator cannot approve their own payment
+  if p_approve and v_order.created_by = p_actor then
+    raise exception 'Maker–checker: a payment cannot be approved by its creator';
+  end if;
+
+  -- locate the nostro (settlement) account for the currency
+  select c.id into v_nostro
+  from public.coa_accounts c
+  where c.tenant_id = v_tenant and c.code = '1100';
+
+  if v_order.tx_type in ('internal_transfer', 'own_transfer') then
+    -- internal: debit source, credit destination (both customer accounts)
+    select * into v_from from public.accounts where id = v_order.from_account_id;
+    if v_from is null then
+      raise exception 'Source account not found';
+    end if;
+    select * into v_to from public.accounts where id = v_order.to_account_id;
+    if v_to is null then
+      -- resolve by account_no
+      select * into v_to from public.accounts
+      where account_no = coalesce(nullif(v_order.to_iban, ''), '')
+         or iban = coalesce(nullif(v_order.to_iban, ''), '');
+      if v_to is null then
+        raise exception 'Destination account not found: %', v_order.to_iban;
+      end if;
+    end if;
+
+    v_lines := jsonb_build_array(
+      jsonb_build_object('account_kind', 'customer', 'account_id', v_order.from_account_id, 'currency', v_order.currency, 'debit', v_order.amount, 'credit', 0, 'memo', v_order.narration),
+      jsonb_build_object('account_kind', 'customer', 'account_id', v_to.id, 'currency', v_order.currency, 'debit', 0, 'credit', v_order.amount, 'memo', v_order.narration)
+    );
+
+    -- fee: 0.5% capped at 20 units, charged to sender, credited to Fee Income
+    v_fee_amount := least(greatest(v_order.amount * 0.005, 0.50), 20.00);
+    select id into v_fee_lines from public.coa_accounts where tenant_id = v_tenant and code = '4000';
+    v_lines := v_lines ||
+      jsonb_build_array(
+        jsonb_build_object('account_kind', 'customer', 'account_id', v_order.from_account_id, 'currency', v_order.currency, 'debit', v_fee_amount, 'credit', 0, 'memo', 'Transfer fee'),
+        jsonb_build_object('account_kind', 'coa', 'account_id', v_fee_lines, 'currency', v_order.currency, 'debit', 0, 'credit', v_fee_amount, 'memo', 'Transfer fee')
+      );
+
+    perform public.post_journal(
+      'Payment ' || v_order.order_no || ' — ' || coalesce(v_order.reference, 'transfer'),
+      v_lines,
+      'payment_order', v_order.order_no::text,
+      now(), null, p_actor
+    );
+
+  elsif v_order.tx_type = 'deposit' then
+    -- sandbox top-up: debit nostro, credit customer account
+    select * into v_from from public.accounts where id = v_order.from_account_id;
+    if v_from is null then
+      raise exception 'Destination account not found';
+    end if;
+    v_lines := jsonb_build_array(
+      jsonb_build_object('account_kind', 'coa', 'account_id', v_nostro, 'currency', v_order.currency, 'debit', v_order.amount, 'credit', 0, 'memo', 'Sandbox deposit in'),
+      jsonb_build_object('account_kind', 'customer', 'account_id', v_from.id, 'currency', v_order.currency, 'debit', 0, 'credit', v_order.amount, 'memo', 'Deposit')
+    );
+    perform public.post_journal(
+      'Deposit ' || v_order.order_no,
+      v_lines,
+      'payment_order', v_order.order_no::text,
+      now(), null, p_actor
+    );
+
+  elsif v_order.tx_type = 'withdrawal' then
+    -- sandbox cash-out: debit customer, credit nostro
+    select * into v_from from public.accounts where id = v_order.from_account_id;
+    if v_from is null then
+      raise exception 'Source account not found';
+    end if;
+    v_lines := jsonb_build_array(
+      jsonb_build_object('account_kind', 'customer', 'account_id', v_from.id, 'currency', v_order.currency, 'debit', v_order.amount, 'credit', 0, 'memo', 'Withdrawal'),
+      jsonb_build_object('account_kind', 'coa', 'account_id', v_nostro, 'currency', v_order.currency, 'debit', 0, 'credit', v_order.amount, 'memo', 'Sandbox withdrawal out')
+    );
+    perform public.post_journal(
+      'Withdrawal ' || v_order.order_no,
+      v_lines,
+      'payment_order', v_order.order_no::text,
+      now(), null, p_actor
+    );
+  else
+    raise exception 'Execution for tx_type % not implemented yet', v_order.tx_type;
+  end if;
+
+  update public.payment_orders
+  set status = 'posted',
+      approved_by = case when p_approve then p_actor else approved_by end,
+      approved_at = case when p_approve then now() else approved_at end,
+      executed_at = now(),
+      fee_amount = case when v_order.tx_type in ('internal_transfer', 'own_transfer') then v_fee_amount else fee_amount end,
+      fee_currency = case when v_order.tx_type in ('internal_transfer', 'own_transfer') then v_order.currency else fee_currency end,
+      updated_at = now()
+  where id = p_order_id
+  returning * into v_order;
+
+  return v_order;
+end;
+$$;

