import { NextResponse } from "next/server";
import { createServerClient } from "@capitech/db";
import { cookies } from "next/headers";

/**
 * Didit KYC — create a verification session server-side.
 * The DIDIT_API_KEY never leaves the server.
 */

// Per-session config — NOT a secret and NOT an env var.
// "Free KYC" workflow from the Didit console.
const WORKFLOW_ID = "29395dea-3494-413e-a9b2-52333b177f79";
const DIDIT_SESSION_URL = "https://verification.didit.me/v3/session/";

export async function POST(req: Request) {
  // 1. Identify the user from YOUR auth session — never trust the browser body.
  const cookieStore = await cookies();
  const supabase = createServerClient({
    getAll: () => cookieStore.getAll(),
    setAll: (cookiesToSet) => {
      try {
        cookiesToSet.forEach(({ name, value, options }) => cookieStore.set(name, value, options));
      } catch {
        // ignore when called from a Server Component context
      }
    },
  });

  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  }

  const apiKey = process.env.DIDIT_API_KEY;
  if (!apiKey) {
    return NextResponse.json({ error: "didit_not_configured" }, { status: 503 });
  }

  // Optional body hints (consent already shown client-side)
  const { language } = await req.json().catch(() => ({}));

  const res = await fetch(DIDIT_SESSION_URL, {
    method: "POST",
    headers: {
      "x-api-key": apiKey,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      workflow_id: WORKFLOW_ID,
      vendor_data: user.id, // stable internal user id — echoed back on every webhook
      callback: "https://app.capitech.me/onboarding?verified=1",
      ...(typeof language === "string" && language.length === 2 ? { language } : {}),
    }),
  });

  if (!res.ok) {
    const detail = await res.text();
    return NextResponse.json({ error: "session_create_failed", detail }, { status: 502 });
  }

  const session = await res.json(); // { session_id, session_token, url, status, ... }
  // Return ONLY what the client needs. session_token is for native SDKs.
  return NextResponse.json({ url: session.url, session_id: session.session_id });
}

import crypto from "node:crypto";
import { NextResponse } from "next/server";
import { createAdminClient } from "@capitech/db";

/**
 * Didit KYC webhook — https://app.capitech.me/api/webhooks/didit
 *
 * Pipeline (in order): timestamp freshness → canonical V2 re-serialise →
 * constant-time HMAC-SHA256 vs X-Signature-V2 → event_id idempotency →
 * dispatch on status (case-sensitive literals) → 2xx within 5 seconds.
 *
 * The webhook is the SOURCE OF TRUTH for verification decisions.
 */

// Whole-number floats (1.0) -> integers (1), recursively — matches Didit's canonicalisation.
function shortenFloats(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(shortenFloats);
  if (v && typeof v === "object") {
    return Object.fromEntries(
      Object.entries(v as Record<string, unknown>).map(([k, x]) => [k, shortenFloats(x)])
    );
  }
  if (typeof v === "number" && !Number.isInteger(v) && v % 1 === 0) return Math.trunc(v);
  return v;
}

// Recursive lexicographic key sort (array order preserved).
function sortKeys(v: unknown): unknown {
  if (Array.isArray(v)) return v.map(sortKeys);
  if (v && typeof v === "object") {
    return Object.keys(v as object)
      .sort()
      .reduce<Record<string, unknown>>((acc, k) => {
        acc[k] = sortKeys((v as Record<string, unknown>)[k]);
        return acc;
      }, {});
  }
  return v;
}

export async function POST(req: Request) {
  const raw = await req.text();
  const sig = req.headers.get("x-signature-v2") ?? "";
  const ts = Number(req.headers.get("x-timestamp"));
  const secret = process.env.DIDIT_WEBHOOK_SECRET;

  // 1. Freshness — reject anything older/newer than 300s (replay protection).
  if (!secret) {
    return NextResponse.json({ error: "didit_webhook_secret_not_configured" }, { status: 503 });
  }
  if (!ts || Number.isNaN(ts) || Math.abs(Date.now() / 1000 - ts) > 300) {
    return new Response("stale", { status: 401 });
  }

  // 2. Canonicalise: shortenFloats → sortKeys → JSON.stringify (unescaped Unicode, JS default).
  let parsed: any;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return new Response("bad body", { status: 400 });
  }
  const canonical = JSON.stringify(sortKeys(shortenFloats(parsed)));

  // 3. Constant-time HMAC-SHA256 compare against X-Signature-V2.
  const expected = crypto.createHmac("sha256", secret).update(canonical, "utf8").digest("hex");
  if (
    sig.length !== expected.length ||
    !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig))
  ) {
    return new Response("bad sig", { status: 401 });
  }

  // 4. Idempotency — dedupe on event_id (unique per delivery attempt).
  const supabase = createAdminClient();
  const { data: existing } = await supabase
    .from("operation_logs")
    .select("id")
    .eq("entity_type", "didit_event")
    .eq("entity_id", parsed.event_id)
    .maybeSingle();
  if (existing) {
    return new Response("ok"); // already processed
  }

  // 5. Apply the decision.
  const vendorData = parsed.vendor_data ?? parsed.metadata?.user_id;
  const sessionId = parsed.session_id;

  try {
    if (parsed.status === "Approved") {
      await applyDecision(vendorData, {
        kyc_status: "approved",
        kyc_level: "level_2",
      });
      await notifyUser(vendorData, "Identity verified", "Your identity verification was approved. Welcome aboard!", "kyc");
    } else if (parsed.status === "Declined") {
      await applyDecision(vendorData, { kyc_status: "rejected" });
      await notifyUser(vendorData, "Verification declined", "We could not verify your identity. Please review the details and try again.", "kyc");
    } else if (parsed.status === "In Review") {
      await applyDecision(vendorData, { kyc_status: "pending" });
      await notifyUser(vendorData, "Verification in review", "Your identity verification is being reviewed by our compliance team.", "kyc");
    } else if (parsed.status === "Resubmitted") {
      // Reviewer asked the user to retry specific steps — reopen to draft.
      await applyDecision(vendorData, { kyc_status: "draft", kyc_level: "unverified" });
      await notifyUser(vendorData, "Action needed", "Some verification documents need to be resubmitted. Please start a new verification.", "kyc");
    } else if (parsed.status === "Kyc Expired") {
      await applyDecision(vendorData, { kyc_status: "draft", kyc_level: "unverified" });
      await notifyUser(vendorData, "Re-verification needed", "Your verification has expired. Please re-verify your identity.", "kyc");
    }
    // Not Started | In Progress | Awaiting User | Abandoned | Expired → no-op (logged below)
  } catch (err) {
    console.error("[didit-webhook] decision apply failed", err);
  }

  // Record idempotency + audit (append-only log), keep the payload for review.
  await supabase.from("operation_logs").insert({
    actor_id: null,
    action: "didit.webhook",
    entity_type: "didit_event",
    entity_id: parsed.event_id,
    details: {
      session_id: sessionId,
      status: parsed.status,
      webhook_type: parsed.webhook_type,
      decision: parsed.decision ?? null,
    },
  }).catch((err) => console.error("[didit-webhook] audit insert failed", err));

  // 6. Return 2xx within 5 seconds. Heavy work is offloaded by Didit's retry + our audit log.
  return new Response("ok");
}

/** Update the customer record linked to vendor_data (the auth user id). */
async function applyDecision(
  vendorData: string | undefined,
  patch: { kyc_status: string; kyc_level?: string }
) {
  if (!vendorData) return;
  const supabase = createAdminClient();
  const { data: customer } = await supabase
    .from("customers")
    .select("id")
    .eq("profile_id", vendorData)
    .maybeSingle();
  if (customer) {
    await supabase.from("customers").update(patch).eq("id", customer.id);
  }
}

/** Push an in-app notification to the user. */
async function notifyUser(vendorData: string | undefined, title: string, body: string, type = "kyc") {
  if (!vendorData) return;
  const supabase = createAdminClient();
  const { data: profile } = await supabase
    .from("profiles")
    .select("id, tenant_id")
    .eq("id", vendorData)
    .maybeSingle();
  if (profile) {
    await supabase.from("notifications").insert({
      tenant_id: profile.tenant_id,
      profile_id: profile.id,
      type,
      title,
      body,
      read: false,
    });
  }
}

"use client";

import { useState } from "react";
import { ShieldCheck, Fingerprint, Loader2 } from "lucide-react";
import { Button } from "@capitech/ui";
import { toast } from "@capitech/ui";
import { DiditSdk } from "@didit-protocol/sdk-web";

/**
 * Didit KYC verification trigger.
 * Shows consent/disclosure first, then opens the hosted verification flow.
 * The webhook (not this callback) is the source of truth for the decision.
 */

interface VerifyButtonProps {
  variant?: "default" | "outline" | "secondary";
  size?: "default" | "lg" | "sm";
  className?: string;
  label?: string;
}

export function VerifyButton({
  variant = "default",
  size = "default",
  className,
  label = "Verify my identity",
}: VerifyButtonProps) {
  const [loading, setLoading] = useState(false);
  const [consent, setConsent] = useState(false);

  async function startVerification() {
    if (!consent) {
      toast.error("Please accept the verification disclosure first");
      return;
    }
    setLoading(true);
    try {
      const res = await fetch("/api/verify", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({}),
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        toast.error(body.error === "unauthorized" ? "Please sign in first" : "Could not start verification. Try again.");
        setLoading(false);
        return;
      }
      const { url } = await res.json();

      DiditSdk.shared.onComplete = (result) => {
        // UI hint only — the webhook is authoritative for the decision.
        if (result.status === "completed") {
          toast.success("Verification submitted — we will notify you once it is reviewed.");
        } else if (result.status === "cancelled") {
          toast.info("Verification cancelled");
        } else {
          toast.error("Verification could not be completed");
        }
      };
      DiditSdk.shared.startVerification({ url }); // opens the Didit modal
    } catch {
      toast.error("Could not start verification. Try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="space-y-3">
      <label className="flex items-start gap-3 rounded-lg border border-border bg-muted/40 p-3 text-xs leading-relaxed text-muted-foreground">
        <input
          type="checkbox"
          checked={consent}
          onChange={(e) => setConsent(e.target.checked)}
          className="mt-0.5 size-4 rounded border-border accent-brand-600"
        />
        <span>
          I consent to <span className="font-medium text-navy-950">Capitech Bank</span> and its
          verification partner <span className="font-medium text-navy-950">Didit</span> collecting
          and processing my identity documents, biometric data and device information to verify my
          identity (KYC), screen against sanctions and PEP lists, and prevent fraud. Data is
          processed in line with our{" "}
          <span className="underline">Privacy Policy</span> and applicable data protection law.
        </span>
      </label>

      <Button
        type="button"
        variant={variant}
        size={size}
        className={className}
        onClick={startVerification}
        disabled={loading || !consent}
      >
        {loading ? <Loader2 className="size-4 animate-spin" /> : <Fingerprint className="size-4" />}
        {loading ? "Opening secure flow…" : label}
      </Button>
    </div>
  );
}

/** Static status chip for display only. */
export function VerifyStatusChip() {
  return (
    <span className="inline-flex items-center gap-1.5 rounded-full bg-emerald-50 px-3 py-1 text-xs font-medium text-emerald-700">
      <ShieldCheck className="size-3.5" /> Verified
    </span>
  );
}

