/**
 * Statement generation — branded PDF (pdfkit) + CSV export.
 * Server-only (pdfkit needs Node buffers).
 */

import { formatMoney, formatDateTime, humanize } from "@capitech/lib";

export interface StatementTx {
  id: string;
  date: string;
  type: string;
  description: string;
  reference: string;
  amount: string; // signed: negative = out
  currency: string;
  balanceAfter?: string | null;
}

export interface StatementData {
  accountLabel: string;
  accountNo: string;
  iban: string;
  currency: string;
  periodStart: string;
  periodEnd: string;
  openingBalance: string;
  closingBalance: string;
  transactions: StatementTx[];
}

const NAVY = "#0b1220";
const BLUE = "#2557eb";
const MUTED = "#64748b";
const LIGHT = "#f1f5f9";
const GRAY = "#94a3b8";

/** Build a CSV string from statement data. */
export function buildCsv(data: StatementData): string {
  const header = ["Date", "Type", "Description", "Reference", "Amount", "Currency", "Balance"];
  const rows = data.transactions.map((t) => [
    formatDateTime(t.date),
    humanize(t.type),
    t.description.replace(/"/g, '""'),
    t.reference,
    t.amount,
    t.currency,
    t.balanceAfter ?? "",
  ]);
  const escape = (cells: string[]) => cells.map((c) => `"${c}"`).join(",");
  return [escape(header), ...rows.map(escape)].join("\r\n");
}

/** Build a branded PDF buffer via pdfkit. */
export async function buildPdf(data: StatementData): Promise<Buffer> {
  const PDFDocument = (await import("pdfkit")).default;

  const doc = new PDFDocument({ size: "A4", margin: 48, bufferPages: true });
  const chunks: Buffer[] = [];
  doc.on("data", (c: Buffer) => chunks.push(c));
  const done = new Promise<Buffer>((resolve) => doc.on("end", () => resolve(Buffer.concat(chunks))));

  /* ---- Header band ---- */
  doc.rect(0, 0, doc.page.width, 92).fill(NAVY);
  doc.fontSize(20).fill("#ffffff").text("Capitech Bank", 48, 26);
  doc.fontSize(9).fill("#8797af").text("Banking beyond borders · capitech.me", 48, 52);
  doc.fontSize(14).fill("#ffffff").text("Account Statement", doc.page.width - 48 - 160, 30, { width: 160, align: "right" });
  doc
    .fontSize(8)
    .fill("#8797af")
    .text(`Period: ${data.periodStart} → ${data.periodEnd}`, doc.page.width - 48 - 160, 52, { width: 160, align: "right" });

  /* ---- Account summary ---- */
  doc.y = 120;
  doc.fontSize(10).fill(NAVY).text(`Account: ${data.accountLabel}`, 48, doc.y);
  doc.fontSize(9).fill(MUTED).text(`Number ${data.accountNo} · ${data.iban} · ${data.currency}`, 48, doc.y + 16);

  const balanceY = doc.y + 40;
  doc.fontSize(9).fill(MUTED).text("Opening balance", 48, balanceY);
  doc
    .fontSize(12)
    .fill(NAVY)
    .text(formatMoney(data.openingBalance, data.currency), 48, balanceY + 14);
  doc.fontSize(9).fill(MUTED).text("Closing balance", doc.page.width - 48 - 120, balanceY, { width: 120, align: "right" });
  doc
    .fontSize(12)
    .fill(NAVY)
    .text(formatMoney(data.closingBalance, data.currency), doc.page.width - 48 - 120, balanceY + 14, { width: 120, align: "right" });

  /* ---- Transactions table ---- */
  const top = balanceY + 64;
  const left = 48;
  const right = doc.page.width - 48;
  const cols = {
    date: left,
    type: left + 85,
    desc: left + 150,
    ref: left + 250,
    amount: right - 110,
    balance: right - 30,
  };
  const rowH = 20;
  const colWidths = {
    date: 85,
    type: 65,
    desc: 100,
    ref: 80,
    amount: 80,
    balance: 80,
  };

  // header row
  doc.rect(left, top, right - left, rowH).fill(LIGHT);
  doc.fontSize(8).fill(MUTED);
  doc.text("Date", cols.date, top + 6);
  doc.text("Type", cols.type, top + 6);
  doc.text("Description", cols.desc, top + 6);
  doc.text("Reference", cols.ref, top + 6);
  doc.text("Amount", cols.amount, top + 6, { width: colWidths.amount, align: "right" });
  doc.text("Balance", cols.balance, top + 6, { width: colWidths.balance, align: "right" });

  let y = top + rowH;
  if (data.transactions.length === 0) {
    doc.fontSize(9).fill(MUTED).text("No transactions in this period.", left, y + 12);
  }
  for (const t of data.transactions) {
    if (y > doc.page.height - 60) {
      doc.addPage();
      y = 48;
    }
    const amount = Number(t.amount);
    doc.fontSize(8).fill(MUTED).text(formatDateTime(t.date), cols.date, y + 6, { width: colWidths.date - 4 });
    doc.fontSize(8).fill(MUTED).text(humanize(t.type).slice(0, 14), cols.type, y + 6, { width: colWidths.type - 4 });
    doc.fontSize(8).fill(NAVY).text(t.description.slice(0, 34), cols.desc, y + 6, { width: colWidths.desc - 4 });
    doc.fontSize(7.5).fill(GRAY).text(t.reference.slice(0, 22), cols.ref, y + 6, { width: colWidths.ref - 4 });
    doc
      .fontSize(8.5)
      .fill(amount < 0 ? "#b91c1c" : "#065f46")
      .text(`${amount < 0 ? "−" : "+"}${formatMoney(Math.abs(amount), t.currency)}`, cols.amount, y + 6, { width: colWidths.amount, align: "right" });
    doc.fontSize(8).fill(NAVY).text(t.balanceAfter ? formatMoney(t.balanceAfter, t.currency) : "", cols.balance, y + 6, { width: colWidths.balance, align: "right" });
    doc.moveTo(left, y + rowH - 1).lineTo(right, y + rowH - 1).strokeColor("#e2e8f0").lineWidth(0.5).stroke();
    y += rowH;
  }

  /* ---- Footer ---- */
  const footerY = doc.page.height - 40;
  doc
    .fontSize(7)
    .fill(GRAY)
    .text(
      "This statement was generated by Capitech Bank (sandbox). Transactions are simulated. Generated " +
        new Date().toISOString().slice(0, 10),
      48,
      footerY,
      { width: doc.page.width - 96, align: "center" }
    );

  doc.end();
  return done;
}

import { NextResponse } from "next/server";
import { createServerClient } from "@capitech/db";
import { cookies } from "next/headers";
import { buildCsv, buildPdf, type StatementData, type StatementTx } from "@/lib/statements";

/**
 * GET /api/statements/[accountId]?format=pdf|csv&from=YYYY-MM-DD&to=YYYY-MM-DD
 * Authenticated; the user may only download statements for their own accounts (RLS).
 */

interface RouteContext {
  params: Promise<{ accountId: string }>;
}

export async function GET(req: Request, { params }: RouteContext) {
  const { accountId } = await params;

  const cookieStore = await cookies();
  const supabase = await createServerClient({
    getAll: () => cookieStore.getAll(),
    setAll: (cookiesToSet) => {
      try {
        cookiesToSet.forEach(({ name, value, options }) => cookieStore.set(name, value, options));
      } catch {
        // ignore
      }
    },
  });

  const {
    data: { user },
  } = await supabase.auth.getUser();
  if (!user) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401 });
  }

  // Account (RLS ensures ownership)
  const { data: account, error: acctError } = await supabase
    .from("accounts")
    .select("id, account_no, iban, currency, nickname, available_balance, products(name)")
    .eq("id", accountId)
    .maybeSingle();
  if (acctError || !account) {
    return NextResponse.json({ error: "not_found" }, { status: 404 });
  }

  const url = new URL(req.url);
  const format = url.searchParams.get("format") === "csv" ? "csv" : "pdf";
  const from = url.searchParams.get("from");
  const to = url.searchParams.get("to");
  const periodStart = from ?? new Date(Date.now() - 30 * 86400000).toISOString().slice(0, 10);
  const periodEnd = to ?? new Date().toISOString().slice(0, 10);

  // Gather transactions: payment_orders (in/out) + card_transactions (out)
  const [orders, cardTx] = await Promise.all([
    supabase
      .from("payment_orders")
      .select("*")
      .or(`from_account_id.eq.${accountId},to_account_id.eq.${accountId}`)
      .gte("created_at", `${periodStart}T00:00:00Z`)
      .lte("created_at", `${periodEnd}T23:59:59Z`)
      .order("created_at", { ascending: false }),
    supabase
      .from("card_transactions")
      .select("*, cards(account_id)")
      .gte("created_at", `${periodStart}T00:00:00Z`)
      .lte("created_at", `${periodEnd}T23:59:59Z`)
      .order("created_at", { ascending: false }),
  ]);

  const txs: StatementTx[] = [];

  for (const o of orders.data ?? []) {
    const isFrom = o.from_account_id === accountId;
    const isTo = o.to_account_id === accountId;
    if (!isFrom && !isTo) continue;
    const amount = isFrom ? -Number(o.amount) : Number(o.amount);
    txs.push({
      id: o.id,
      date: o.created_at,
      type: o.tx_type,
      description: o.narration ?? o.to_beneficiary_name ?? o.order_no,
      reference: o.reference ?? o.order_no,
      amount: amount.toFixed(2),
      currency: o.currency,
    });
  }
  for (const c of cardTx.data ?? []) {
    if (c.cards?.account_id !== accountId) continue;
    const amount = c.tx_type === "card_refund" ? Number(c.amount) : -Number(c.amount);
    txs.push({
      id: c.id,
      date: c.created_at,
      type: c.tx_type,
      description: `${c.merchant_name ?? "Card payment"} (•••• ${c.card_id})`,
      reference: c.mcc ?? "",
      amount: amount.toFixed(2),
      currency: c.currency,
    });
  }

  txs.sort((a, b) => (a.date < b.date ? 1 : -1));

  // Derive running balances: newest-first, start at current balance
  const current = Number(account.available_balance);
  let running = current;
  const withBalances: StatementTx[] = [];
  for (const t of txs) {
    withBalances.push({ ...t, balanceAfter: running.toFixed(2) });
    running -= Number(t.amount); // balance before this tx
  }
  withBalances.reverse(); // chronological for the report
  const openingBalance = running.toFixed(2);

  const statement: StatementData = {
    accountLabel: account.nickname ?? account.products?.name ?? "Account",
    accountNo: account.account_no,
    iban: account.iban ?? "",
    currency: account.currency,
    periodStart,
    periodEnd,
    openingBalance,
    closingBalance: current.toFixed(2),
    transactions: withBalances,
  };

  if (format === "csv") {
    const csv = buildCsv(statement);
    return new Response(csv, {
      headers: {
        "Content-Type": "text/csv; charset=utf-8",
        "Content-Disposition": `attachment; filename="statement-${account.account_no}.csv"`,
      },
    });
  }

  const pdf = await buildPdf(statement);
  return new Response(new Uint8Array(pdf), {
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": `attachment; filename="statement-${account.account_no}.pdf"`,
    },
  });
}

