-- ============================================================
-- Capitech Bank — 0012: Open API + Crypto + security hardening
-- Paste into: Supabase Dashboard → SQL Editor → Run
-- ============================================================

-- ------------------------------------------------------------
-- 1) api_keys: bind keys to an owner (customer or organization)
-- ------------------------------------------------------------
alter table public.api_keys
  add column if not exists owner_type text check (owner_type in ('customer', 'organization')),
  add column if not exists owner_id uuid;

create index if not exists api_keys_owner_idx on public.api_keys (owner_type, owner_id);

-- ------------------------------------------------------------
-- 2) SECURITY HARDENING — post_journal ownership enforcement
--    Customers may only post journal lines on accounts they own.
--    Staff and system (service-role / cron, p_actor null) bypass.
-- ------------------------------------------------------------
create or replace function public.post_journal(
  p_description text,
  p_lines jsonb,
  p_reference_type text default null,
  p_reference_id text default null,
  p_entry_date timestamptz default now(),
  p_tenant uuid default null,
  p_actor uuid default auth.uid()
)
returns public.gl_entries
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tenant uuid := coalesce(p_tenant, public.current_tenant_id());
  v_entry public.gl_entries;
  v_line jsonb;
  v_kind text;
  v_account_id uuid;
  v_coa_id uuid;
  v_currency char(3);
  v_debit numeric(20,2);
  v_credit numeric(20,2);
  v_memo text;
  v_dr_sum numeric(20,2) := 0;
  v_cr_sum numeric(20,2) := 0;
  v_bal public.accounts%rowtype;
  v_normal_side text;
begin
  if v_tenant is null then
    raise exception 'Not authenticated';
  end if;
  if jsonb_array_length(p_lines) = 0 then
    raise exception 'Journal must contain at least one line';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_kind := v_line ->> 'account_kind';
    v_account_id := (v_line ->> 'account_id')::uuid;
    v_currency := v_line ->> 'currency';
    v_debit := coalesce((v_line ->> 'debit')::numeric, 0);
    v_credit := coalesce((v_line ->> 'credit')::numeric, 0);
    v_memo := v_line ->> 'memo';

    if v_kind = 'customer' then
      select * into v_bal from public.accounts where id = v_account_id;
      if v_bal is null then
        raise exception 'Account % not found', v_account_id;
      end if;
      if v_bal.tenant_id <> v_tenant then
        raise exception 'Account % not in tenant', v_account_id;
      end if;
      -- OWNERSHIP ENFORCEMENT (new): customer callers can only move their own money
      if p_actor is not null
         and not public.is_staff()
         and not public.is_account_owner(v_account_id) then
        raise exception 'Account % is not owned by the caller', v_account_id;
      end if;
      if v_bal.currency <> v_currency then
        raise exception 'Account % currency mismatch (% <> %)', v_account_id, v_bal.currency, v_currency;
      end if;
      if v_bal.status <> 'active' or v_bal.frozen then
        raise exception 'Account % is not available for transactions', v_account_id;
      end if;
      if v_debit > 0 then
        if v_debit > v_bal.available_balance + 0.0001 then
          raise exception 'Insufficient funds on account % (available % < debit %)', v_account_id, v_bal.available_balance, v_debit;
        end if;
      end if;
      v_dr_sum := v_dr_sum + v_debit;
      v_cr_sum := v_cr_sum + v_credit;
    elsif v_kind = 'coa' then
      v_coa_id := v_account_id;
      if not exists (
        select 1 from public.coa_accounts
        where id = v_coa_id and tenant_id = v_tenant
      ) then
        raise exception 'COA account % not found', v_coa_id;
      end if;
      v_dr_sum := v_dr_sum + v_debit;
      v_cr_sum := v_cr_sum + v_credit;
    else
      raise exception 'Invalid account_kind: %', v_kind;
    end if;
  end loop;

  if v_dr_sum <> v_cr_sum then
    raise exception 'Journal does not balance: debits % <> credits %', v_dr_sum, v_cr_sum;
  end if;

  insert into public.gl_entries (
    tenant_id, journal_no, entry_date, post_date, description,
    reference_type, reference_id, status, created_by, approved_by, approved_at
  )
  values (
    v_tenant, public.next_journal_no(), p_entry_date, now(), p_description,
    p_reference_type, p_reference_id, 'posted', p_actor, p_actor, now()
  )
  returning * into v_entry;

  for v_line in select * from jsonb_array_elements(p_lines)
  loop
    v_kind := v_line ->> 'account_kind';
    v_account_id := (v_line ->> 'account_id')::uuid;
    v_currency := v_line ->> 'currency';
    v_debit := coalesce((v_line ->> 'debit')::numeric, 0);
    v_credit := coalesce((v_line ->> 'credit')::numeric, 0);
    v_memo := v_line ->> 'memo';

    insert into public.gl_entry_lines (
      tenant_id, entry_id, coa_account_id, customer_account_id,
      currency, debit, credit, memo
    )
    values (
      v_tenant, v_entry.id,
      case when v_kind = 'coa' then v_account_id else null end,
      case when v_kind = 'customer' then v_account_id else null end,
      v_currency, v_debit, v_credit, v_memo
    );

    if v_kind = 'customer' then
      update public.accounts
      set ledger_balance = ledger_balance - v_debit + v_credit,
          available_balance = available_balance - v_debit + v_credit,
          updated_at = now()
      where id = v_account_id;
    else
      select normal_side into v_normal_side
      from public.coa_accounts where id = v_account_id;

      insert into public.balances (tenant_id, coa_account_id, currency)
      values (v_tenant, v_account_id, v_currency)
      on conflict (coa_account_id, currency) do nothing;

      update public.balances
      set ledger_balance = ledger_balance +
            case when v_normal_side = 'debit' then v_debit - v_credit
                 else v_credit - v_debit end,
          available_balance = available_balance +
            case when v_normal_side = 'debit' then v_debit - v_credit
                 else v_credit - v_debit end,
          last_transaction_at = now(),
          updated_at = now()
      where coa_account_id = v_account_id and currency = v_currency;
    end if;
  end loop;

  return v_entry;
end;
$$;

-- ------------------------------------------------------------
-- 3) Crypto: price cache + order execution engine
-- ------------------------------------------------------------
create table if not exists public.crypto_prices (
  asset text primary key,
  price_usd numeric(24,12),
  change_24h numeric(8,4),
  market_cap numeric(30,2),
  updated_at timestamptz not null default now()
);

create or replace function public.execute_crypto_order(
  p_account_id uuid,
  p_side text,
  p_asset text,
  p_amount_fiat numeric(20,2),
  p_price numeric(24,12)
)
returns public.crypto_orders
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tenant uuid := public.current_tenant_id();
  v_account public.accounts%rowtype;
  v_amount_asset numeric(36,18);
  v_coa_crypto uuid;
  v_order public.crypto_orders;
  v_wallet public.crypto_wallets%rowtype;
begin
  if v_tenant is null then
    raise exception 'Not authenticated';
  end if;
  if p_side not in ('buy', 'sell') then
    raise exception 'side must be buy or sell';
  end if;
  if p_amount_fiat <= 0 or p_price <= 0 then
    raise exception 'amount and price must be positive';
  end if;

  select * into v_account from public.accounts
  where id = p_account_id and tenant_id = v_tenant;
  if v_account is null then
    raise exception 'Account not found';
  end if;

  v_amount_asset := round(p_amount_fiat / p_price, 8);

  select id into v_coa_crypto from public.coa_accounts
  where tenant_id = v_tenant and code = '2300';

  -- ledger: buy = debit fiat / credit crypto liability; sell = reverse
  perform public.post_journal(
    case when p_side = 'buy' then 'Crypto purchase ' else 'Crypto sale ' end || p_asset,
    jsonb_build_array(
      jsonb_build_object('account_kind', 'customer', 'account_id', p_account_id,
                         'currency', v_account.currency,
                         'debit', case when p_side = 'buy' then p_amount_fiat else 0 end,
                         'credit', case when p_side = 'sell' then p_amount_fiat else 0 end,
                         'memo', p_asset),
      jsonb_build_object('account_kind', 'coa', 'account_id', v_coa_crypto,
                         'currency', v_account.currency,
                         'debit', case when p_side = 'sell' then p_amount_fiat else 0 end,
                         'credit', case when p_side = 'buy' then p_amount_fiat else 0 end,
                         'memo', p_asset)
    ),
    'crypto_order', null,
    now(), v_tenant, auth.uid()
  );

  -- wallet balance update
  select * into v_wallet from public.crypto_wallets
  where account_id = p_account_id and asset = upper(p_asset);
  if v_wallet is null then
    if p_side = 'sell' then
      raise exception 'No wallet for % — nothing to sell', p_asset;
    end if;
    insert into public.crypto_wallets (tenant_id, account_id, asset, balance, address)
    values (v_tenant, p_account_id, upper(p_asset), 0, '0x' || encode(gen_random_bytes(20), 'hex'));
    select * into v_wallet from public.crypto_wallets
    where account_id = p_account_id and asset = upper(p_asset);
  end if;

  if p_side = 'sell' and v_wallet.balance < v_amount_asset then
    raise exception 'Insufficient % balance (available % < %)', p_asset, v_wallet.balance, v_amount_asset;
  end if;

  update public.crypto_wallets
  set balance = balance + case when p_side = 'buy' then v_amount_asset else -v_amount_asset end,
      updated_at = now()
  where id = v_wallet.id;

  insert into public.crypto_orders (
    tenant_id, account_id, order_type, asset, side,
    amount_fiat, amount_asset, price, status
  ) values (
    v_tenant, p_account_id, 'market', upper(p_asset), p_side,
    p_amount_fiat, v_amount_asset, p_price, 'filled'
  )
  returning * into v_order;

  return v_order;
end;
$$;

grant execute on function public.post_journal(text, jsonb, text, text, timestamptz, uuid, uuid) to authenticated;
grant execute on function public.execute_crypto_order(uuid, text, text, numeric, numeric) to authenticated;

{
  "name": "@capitech/openapi",
  "version": "0.1.0",
  "private": true,
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@capitech/db": "workspace:*"
  },
  "devDependencies": {
    "typescript": "^5.7.0"
  }
}

import { createHash, createHmac, randomBytes } from "node:crypto";
import { createAdminClient } from "@capitech/db";

/**
 * Capitech Open API — key management, bearer auth, webhook dispatch.
 * Server-only (uses the service-role admin client for lookups).
 */

export const API_KEY_PREFIX = "capt_live_";

export const SCOPES = {
  READ: "read",
  TRANSFERS: "write:transfers",
  WEBHOOKS: "webhooks",
  ADMIN: "admin",
} as const;

export type Scope = (typeof SCOPES)[keyof typeof SCOPES];

export interface ApiKeyContext {
  keyId: string;
  tenantId: string;
  ownerType: "customer" | "organization";
  ownerId: string;
  scopes: Scope[];
}

/** sha256 hex — how API keys are stored at rest (raw key is shown once). */
export function hashKey(rawKey: string): string {
  return createHash("sha256").update(rawKey).digest("hex");
}

/** Generate a new raw API key (the only time it is ever visible). */
export function generateApiKey(): { raw: string; hash: string; prefix: string } {
  const raw = `${API_KEY_PREFIX}${randomBytes(24).toString("base64url")}`;
  return { raw, hash: hashKey(raw), prefix: raw.slice(0, 14) };
}

/** Resolve a bearer token to a key context (or null). Updates last_used_at. */
export async function authenticateApiKey(
  authorizationHeader: string | null
): Promise<{ ctx: ApiKeyContext | null; error?: string }> {
  if (!authorizationHeader || !authorizationHeader.startsWith("Bearer ")) {
    return { ctx: null, error: "missing_bearer" };
  }
  const raw = authorizationHeader.slice("Bearer ".length).trim();
  const hash = hashKey(raw);
  const supabase = createAdminClient();
  const { data: key, error } = await supabase
    .from("api_keys")
    .select("id, tenant_id, owner_type, owner_id, scopes, status, expires_at")
    .eq("key_hash", hash)
    .maybeSingle();
  if (error || !key) {
    return { ctx: null, error: "invalid_key" };
  }
  if (key.status !== "active") {
    return { ctx: null, error: "revoked" };
  }
  if (key.expires_at && new Date(key.expires_at).getTime() < Date.now()) {
    return { ctx: null, error: "expired" };
  }
  if (!key.owner_id) {
    return { ctx: null, error: "key_not_bound" };
  }
  // best-effort last-used touch
  await supabase.from("api_keys").update({ last_used_at: new Date().toISOString() }).eq("id", key.id).catch(() => {});
  return {
    ctx: {
      keyId: key.id,
      tenantId: key.tenant_id,
      ownerType: key.owner_type,
      ownerId: key.owner_id,
      scopes: (key.scopes ?? ["read"]) as Scope[],
    },
  };
}

/** Check that a context has a required scope. */
export function hasScope(ctx: ApiKeyContext, scope: Scope): boolean {
  return ctx.scopes.includes(scope) || ctx.scopes.includes("admin");
}

/* ============================================================
   Webhook dispatch
   ============================================================ */

export const WEBHOOK_EVENTS = [
  "payment.created",
  "payment.updated",
  "customer.created",
] as const;

export type WebhookEvent = (typeof WEBHOOK_EVENTS)[number];

/** HMAC signature header value for a webhook payload. */
export function signWebhookPayload(secret: string, payload: unknown): string {
  return createHmac("sha256", secret).update(JSON.stringify(payload)).digest("hex");
}

/**
 * Dispatch an event to all active webhook endpoints subscribed to it.
 * Best-effort: failures are recorded in webhook_events, never thrown.
 */
export async function dispatchWebhooks(event: WebhookEvent, payload: unknown, tenantId: string) {
  const supabase = createAdminClient();
  const { data: endpoints } = await supabase
    .from("webhook_endpoints")
    .select("id, url, secret, events")
    .eq("tenant_id", tenantId)
    .eq("active", true);

  for (const ep of endpoints ?? []) {
    if (!(ep.events ?? []).includes(event)) continue;
    const body = JSON.stringify({ event, data: payload, sent_at: new Date().toISOString() });
    const signature = signWebhookPayload(ep.secret, JSON.parse(body));
    try {
      const res = await fetch(ep.url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-Capitech-Event": event,
          "X-Capitech-Signature": signature,
          "User-Agent": "Capitech-Webhook/1.0",
        },
        body,
        // fail fast so we never hold a request hostage
        signal: AbortSignal.timeout(5000),
      });
      await supabase.from("webhook_events").insert({
        tenant_id: tenantId,
        endpoint_id: ep.id,
        event_type: event,
        payload: JSON.parse(body),
        status: res.ok ? "delivered" : "failed",
        attempts: 1,
      });
    } catch (err) {
      await supabase.from("webhook_events").insert({
        tenant_id: tenantId,
        endpoint_id: ep.id,
        event_type: event,
        payload: JSON.parse(body),
        status: "failed",
        attempts: 1,
      }).catch(() => {});
    }
  }
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { createAdminClient } from "@capitech/db";
import { authenticateApiKey, hasScope, SCOPES, type ApiKeyContext } from "@capitech/openapi";

/**
 * Shared Open API helpers: resolve the caller from the Bearer key,
 * load the owner's accounts, and build uniform error responses.
 */

export function apiError(error: string, status = 401, detail?: unknown) {
  return NextResponse.json({ error, ...(detail !== undefined ? { detail } : {}) }, { status });
}

/** Authenticate the request and return the key context. */
export async function requireApiKey(
  req: NextRequest,
  scope: keyof typeof SCOPES
): Promise<{ ctx?: ApiKeyContext; response?: NextResponse }> {
  const { ctx, error } = await authenticateApiKey(req.headers.get("authorization"));
  if (!ctx) {
    return { response: apiError(error ?? "unauthorized") };
  }
  if (!hasScope(ctx, SCOPES[scope])) {
    return { response: apiError("insufficient_scope", 403) };
  }
  return { ctx };
}

/** Load the accounts owned by the key's owner. */
export async function ownerAccounts(ctx: ApiKeyContext) {
  const supabase = createAdminClient();
  const { data, error } = await supabase
    .from("accounts")
    .select("id, account_no, iban, swift_bic, currency, status, nickname, ledger_balance, available_balance, frozen, products(name, product_type)")
    .eq("owner_type", ctx.ownerType)
    .eq("owner_id", ctx.ownerId)
    .eq("status", "active")
    .order("created_at", { ascending: false });
  if (error) throw error;
  return data ?? [];
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { requireApiKey, ownerAccounts } from "./helpers";

/** GET /api/open/v1/accounts — list accounts owned by the API key's owner. */
export async function GET(req: NextRequest) {
  const { ctx, response } = await requireApiKey(req, "read");
  if (response) return response;

  try {
    const accounts = await ownerAccounts(ctx!);
    return NextResponse.json({
      data: accounts.map((a: any) => ({
        id: a.id,
        account_no: a.account_no,
        iban: a.iban,
        bic: a.swift_bic,
        currency: a.currency,
        status: a.status,
        nickname: a.nickname,
        product: a.products?.[0]?.name ?? a.products?.name ?? null,
        product_type: a.products?.[0]?.product_type ?? a.products?.product_type ?? null,
        ledger_balance: a.ledger_balance,
        available_balance: a.available_balance,
        frozen: a.frozen,
      })),
    });
  } catch (err) {
    console.error("[openapi] accounts error", err);
    return NextResponse.json({ error: "internal" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { createAdminClient } from "@capitech/db";
import { requireApiKey, ownerAccounts, apiError } from "./helpers";

interface RouteContext {
  params: Promise<{ id: string }>;
}

/** GET /api/open/v1/accounts/[id] — account detail (owner-scoped). */
export async function GET(req: NextRequest, { params }: RouteContext) {
  const { id } = await params;
  const { ctx, response } = await requireApiKey(req, "read");
  if (response) return response;

  const accounts = await ownerAccounts(ctx!);
  const account = accounts.find((a: any) => a.id === id);
  if (!account) return apiError("not_found", 404);

  return NextResponse.json({ data: account });
}

/** GET /api/open/v1/accounts/[id]/transactions — statement-style transactions. */
export async function transactions(req: NextRequest, { params }: RouteContext) {
  const { id } = await params;
  const { ctx, response } = await requireApiKey(req, "read");
  if (response) return response;

  const accounts = await ownerAccounts(ctx!);
  const account = accounts.find((a: any) => a.id === id);
  if (!account) return apiError("not_found", 404);

  const supabase = createAdminClient();
  const [orders, cardTx] = await Promise.all([
    supabase
      .from("payment_orders")
      .select("*")
      .or(`from_account_id.eq.${id},to_account_id.eq.${id}`)
      .order("created_at", { ascending: false })
      .limit(100),
    supabase
      .from("card_transactions")
      .select("*, cards(account_id)")
      .order("created_at", { ascending: false })
      .limit(100),
  ]);

  const txs = (orders.data ?? [])
    .filter((o: any) => o.from_account_id === id || o.to_account_id === id)
    .map((o: any) => ({
      id: o.id,
      type: o.tx_type,
      status: o.status,
      amount: o.amount,
      currency: o.currency,
      direction: o.from_account_id === id ? "out" : "in",
      reference: o.reference ?? o.order_no,
      narration: o.narration,
      created_at: o.created_at,
    }))
    .concat(
      (cardTx.data ?? [])
        .filter((c: any) => c.cards?.account_id === id)
        .map((c: any) => ({
          id: c.id,
          type: c.tx_type,
          status: c.status,
          amount: c.amount,
          currency: c.currency,
          direction: c.tx_type === "card_refund" ? "in" : "out",
          reference: c.mcc ?? "",
          narration: c.merchant_name,
          created_at: c.created_at,
        }))
    )
    .sort((a, b) => (a.created_at < b.created_at ? 1 : -1));

  return NextResponse.json({ data: txs });
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { createAdminClient } from "@capitech/db";
import { requireApiKey, ownerAccounts, apiError } from "./helpers";
import { dispatchWebhooks } from "@capitech/openapi";

/**
 * POST /api/open/v1/transfers — create a payment order.
 * Body: { from_account_id, amount, currency, to_account_id | to_iban, reference?, narration? }
 * Maker–checker: the order is created as "pending" and must be authorised by the back office.
 */

export async function POST(req: NextRequest) {
  const { ctx, response } = await requireApiKey(req, "write:transfers");
  if (response) return response;

  const body = await req.json().catch(() => ({}));
  const { from_account_id, amount, currency, to_account_id, to_iban, reference, narration } = body as any;

  if (!from_account_id || !amount || !currency || (!to_account_id && !to_iban)) {
    return apiError("bad_request", 400, "from_account_id, amount, currency and a destination are required");
  }
  if (typeof amount !== "number" || amount <= 0) {
    return apiError("bad_request", 400, "amount must be a positive number");
  }

  // The source account must belong to the key owner
  const accounts = await ownerAccounts(ctx!);
  const source = accounts.find((a: any) => a.id === from_account_id);
  if (!source) return apiError("forbidden", 403, "from_account_id is not owned by this key");
  if (source.currency !== currency) return apiError("bad_request", 400, "currency does not match source account");

  // Resolve a member profile to act as created_by (maker)
  const supabase = createAdminClient();
  let makerProfileId: string | null = null;
  if (ctx!.ownerType === "organization") {
    const { data: member } = await supabase
      .from("organization_members")
      .select("profile_id")
      .eq("organization_id", ctx!.ownerId)
      .eq("status", "active")
      .limit(1)
      .maybeSingle();
    makerProfileId = member?.profile_id ?? null;
  } else {
    const { data: customer } = await supabase
      .from("customers")
      .select("profile_id")
      .eq("id", ctx!.ownerId)
      .maybeSingle();
    makerProfileId = customer?.profile_id ?? null;
  }
  if (!makerProfileId) {
    return apiError("unprocessable", 422, "no authorised user linked to this key");
  }

  const txType = to_account_id ? "internal_transfer" : "withdrawal";

  const { data: order, error } = await supabase
    .from("payment_orders")
    .insert({
      tenant_id: ctx!.tenantId,
      order_no: `PAY-${Date.now()}-${Math.floor(Math.random() * 99999)}`,
      tx_type: txType,
      status: "pending",
      amount,
      currency,
      from_account_id,
      to_account_id: to_account_id ?? null,
      to_iban: to_iban ? String(to_iban).replace(/\s/g, "") : null,
      to_beneficiary_name: body.to_beneficiary_name ?? null,
      reference: reference ?? null,
      narration: narration ?? null,
      created_by: makerProfileId,
    })
    .select()
    .single();
  if (error || !order) {
    console.error("[openapi] transfer insert failed", error);
    return apiError("internal", 500);
  }

  // Notify subscribers
  await dispatchWebhooks(
    "payment.created",
    {
      order_no: order.order_no,
      tx_type: order.tx_type,
      amount: order.amount,
      currency: order.currency,
      status: order.status,
    },
    ctx!.tenantId
  ).catch(() => {});

  return NextResponse.json({ data: order }, { status: 201 });
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { createAdminClient } from "@capitech/db";
import { requireApiKey, apiError } from "./helpers";
import { randomBytes } from "node:crypto";

/**
 * Webhook endpoint management (Open API).
 * GET  /api/open/v1/webhooks — list this key owner's endpoints + recent deliveries
 * POST /api/open/v1/webhooks — register a new endpoint (url + subscribed events)
 */

export async function GET(req: NextRequest) {
  const { ctx, response } = await requireApiKey(req, "webhooks");
  if (response) return response;
  const supabase = createAdminClient();
  const { data: endpoints } = await supabase
    .from("webhook_endpoints")
    .select("id, url, events, active, created_at")
    .eq("tenant_id", ctx!.tenantId)
    .order("created_at", { ascending: false });
  return NextResponse.json({ data: endpoints ?? [] });
}

export async function POST(req: NextRequest) {
  const { ctx, response } = await requireApiKey(req, "webhooks");
  if (response) return response;

  const body = await req.json().catch(() => ({}));
  const { url, events } = body as { url?: string; events?: string[] };
  if (!url || !/^https:\/\//.test(url)) {
    return apiError("bad_request", 400, "url must be an https:// endpoint");
  }
  const allowed = ["payment.created", "payment.updated", "customer.created"];
  const subscribed = (events ?? []).filter((e) => allowed.includes(e));
  if (subscribed.length === 0) {
    return apiError("bad_request", 400, "events must be a non-empty subset of " + allowed.join(", "));
  }

  const supabase = createAdminClient();
  const { data: endpoint, error } = await supabase
    .from("webhook_endpoints")
    .insert({
      tenant_id: ctx!.tenantId,
      url,
      events: subscribed,
      secret: randomBytes(24).toString("hex"),
      active: true,
    })
    .select()
    .single();
  if (error) {
    console.error("[openapi] webhook create failed", error);
    return apiError("internal", 500);
  }
  return NextResponse.json({ data: endpoint }, { status: 201 });
}

